import type { WorkflowPullRequestReceipt } from "#internet/workflow/types";

export type WorkflowTeamPhase = "research" | "review";
export type WorkflowTeamLane = "A" | "B";

export interface WorkflowPromptContext {
	readonly objective: string;
	readonly repository: string;
	readonly baseRevision: string;
}

export interface WorkflowReviewPromptContext extends WorkflowPromptContext {
	readonly pullRequest: WorkflowPullRequestReceipt;
	readonly reviewCycle: number;
}

function laneFocus(phase: WorkflowTeamPhase, lane: WorkflowTeamLane): string {
	if (phase === "research") {
		return lane === "A"
			? "Prioritize architecture, repository integration points, implementation sequencing, and compatibility with the stated objective."
			: "Independently challenge assumptions; prioritize failure modes, tests, edge cases, security/correctness risks, and a simpler alternative when one exists.";
	}
	return lane === "A"
		? "Review for correctness, architecture, scope discipline, regressions, and whether the implementation actually satisfies the objective."
		: "Review adversarially for edge cases, tests, security/reliability issues, concurrency/state bugs, and hidden failure modes.";
}

export class WorkflowTeamPromptBuilder {
	research(context: WorkflowPromptContext, lane: WorkflowTeamLane): string {
		return [
			`Workflow research lane: ${lane}`,
			`Repository: ${context.repository}`,
			`Target base revision: ${context.baseRevision}`,
			"",
			"Objective:",
			context.objective,
			"",
			laneFocus("research", lane),
			"",
			"Analyze independently from the other workflow lane. Use the repository and exact base revision as authoritative scope. Produce one implementation-ready final answer for the writer: concrete files/components to inspect, recommended changes, validation strategy, risks, and any blocker. Do not assume another agent will summarize your final answer.",
		].join("\n");
	}

	review(context: WorkflowReviewPromptContext, lane: WorkflowTeamLane): string {
		const pullRequest = context.pullRequest;
		return [
			`Workflow review lane: ${lane}`,
			`Repository: ${context.repository}`,
			`Original base revision: ${context.baseRevision}`,
			`Pull request: ${pullRequest.url}`,
			`PR number: ${pullRequest.number}`,
			`Review cycle: ${context.reviewCycle}`,
			`Exact PR head SHA to review: ${pullRequest.headSha}`,
			"",
			"Objective:",
			context.objective,
			"",
			laneFocus("review", lane),
			"",
			'Review the actual PR at the exact head SHA above. Treat earlier review cycles only as context; findings must be valid for this head. Return exactly one JSON object and no markdown or surrounding prose. Use {"verdict":"PASS","reviewedHeadSha":"the exact 40-character PR head SHA above","summary":"concise evidence-based summary"} when no material issue remains. Otherwise use {"verdict":"CHANGES_REQUIRED","reviewedHeadSha":"the exact 40-character PR head SHA above","findings":[{"severity":"high|medium|low","location":"file/area","issue":"concrete problem","remediation":"required fix"}]}. The complete JSON object is the reviewer payload delivered verbatim to the writer; do not rely on another agent to summarize it.',
		].join("\n");
	}
}
